#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>

long long fib(int n) {
    long long a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        long long t = a + b;
        a = b;
        b = t;
    }
    return a;
}

bool is_prime(int n) {
    if (n < 2) {
        return false;
    }
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

std::vector<int> primes_below(int limit) {
    std::vector<int> primes;
    for (int n = 2; n < limit; n++) {
        if (is_prime(n)) {
            primes.push_back(n);
        }
    }
    return primes;
}

int main() {
    std::cout << "fib(10) = " << fib(10) << '\n';
    std::cout << "gcd(54, 24) = " << std::gcd(54, 24) << '\n';

    std::cout << "primes:";
    for (int p : primes_below(50)) {
        std::cout << ' ' << p;
    }
    std::cout << '\n';

    std::vector<int> squares(19);
    for (int i = 0; i < 19; i++) {
        squares[i] = (i + 1) * (i + 1);
    }
    bool found = std::binary_search(squares.begin(), squares.end(), 144);
    std::cout << "contains 144: " << std::boolalpha << found << '\n';
    return 0;
}

